import assert from 'node:assert/strict';

export async function runMotionRemoveSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{name:'Exterior',text:'Fuera del grupo'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),assets:project.assets.images.length,outside:sec().elements[0]}));
  async function frame(){await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-motion-canvas]'));return (await page.$('.nw-motion-dialog iframe')).contentFrame();}
  async function layers(){return page.$$eval('[data-motion-layer]',ns=>ns.map(n=>n.dataset.motionLayer));}
  async function choose(id){await page.click('[data-motion-layer="'+id+'"]');}
  async function remove(id){await choose(id);await page.click('[data-motion-element-remove]');await page.waitForFunction(id=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelector('[data-motion-canvas]')&&!d.querySelector('[data-id="'+id+'"]');},{},id);assert.ok(!(await layers()).includes(id));}
  async function fresh(){await page.click('.tb-left [data-motion-open]');await frame();await page.click('[data-motion-library-tab="elements"]');return layers();}
  const original=await fresh(),focusId=await page.evaluate(()=>document.querySelector('.nw-motion-dialog iframe').contentDocument.querySelector('.sc').dataset.id);await remove(original[0]);assert.equal(await page.$eval('[data-motion-layer][aria-pressed="true"]',n=>n.dataset.motionLayer),original[1]);await remove(original[4]);await remove(original[5]);const survivors=[original[1],original[2],original[3]];assert.deepEqual(await layers(),survivors);
  await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');assert.equal((await layers()).length,6);await page.click('[data-motion-template="iso-focus"]');await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.sc')?.dataset.id===id,{},focusId);assert.deepEqual(await layers(),survivors);
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);await page.click('[data-motion-insert-group]');
  const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {project:JSON.stringify(project),gid:g.id,members:sec().elements.filter(e=>e.parent===g.id),assets:project.assets.images.length,outside:sec().elements[0],selected:selection[0]};});assert.deepEqual(inserted.members.map(e=>e.id),survivors);assert.equal(inserted.assets,before.assets+2,'Only surviving image resources are inserted');assert.deepEqual(inserted.outside,before.outside);assert.ok(survivors.includes(inserted.selected));
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await frame();await page.click('[data-motion-library-tab="elements"]');await remove(original[2]);await choose(original[1]);await page.click('[data-motion-duplicate]');const added=(await layers()).find(id=>!survivors.includes(id));await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected'),{},added);await page.click('[data-motion-save]');
  const saved=await page.evaluate(gid=>({project:JSON.stringify(project),members:sec().elements.filter(e=>e.parent===gid),groups:sec().elements.filter(e=>e.nwMotionInstance).length,assets:project.assets.images.length,outside:sec().elements[0],selected:selection[0],current:sec().elements[curEl]?.id}),inserted.gid);assert.equal(saved.groups,1);assert.equal(saved.selected,inserted.gid,'Removing the main selection selects its group');assert.equal(saved.current,saved.selected,'Main inspector index remains consistent');assert.deepEqual(saved.members.map(e=>e.id),[original[1],original[3],added]);assert.deepEqual(saved.members.find(e=>e.id===original[1]),inserted.members[0]);assert.deepEqual(saved.members.find(e=>e.id===original[3]),inserted.members[2]);assert.equal(saved.assets,inserted.assets,'Existing resources are preserved for other uses');assert.deepEqual(saved.outside,before.outside);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await frame();await page.click('[data-motion-library-tab="elements"]');assert.deepEqual(await layers(),saved.members.map(e=>e.id));await remove(added);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='remove-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#remove-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},inserted.gid);const exported=await page.evaluate(({gid,removed,kept,outside})=>{const f=document.querySelector('#remove-export'),d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].set(0);return {removed:removed.map(id=>!!d.querySelector('[data-id="'+id+'"]')),images:d.querySelector('[data-id="'+gid+'"]')?.querySelectorAll('.im-hov').length,z:d.querySelector('[data-id="'+kept+'"]')?.style.getPropertyValue('--nw-sd-z'),outside:d.querySelector('[data-id="'+outside+'"]')?.textContent};},{gid:inserted.gid,removed:[original[0],original[2],original[4],original[5]],kept:original[1],outside:before.outside.id});assert.deepEqual(exported.removed,[false,false,false,false]);assert.equal(exported.images,2);assert.equal(exported.z,'-160.00px');assert.equal(exported.outside,before.outside.text);
  // A single image still inserts as a new scene without assuming a second member.
  const single=await fresh();for(const id of single.slice(1))await remove(id);await choose(single[0]);assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await page.click('[data-motion-element-remove]');assert.deepEqual(await layers(),[single[0]]);const assetsBeforeScene=await page.evaluate(()=>project.assets.images.length);await page.click('[data-motion-insert]');const scene=await page.evaluate(()=>({count:page().sections.length,elements:sec().elements,selected:selection[0],mode:NAGWEB_STORY_EDITOR.canvasMode(),assets:project.assets.images.length}));assert.equal(scene.count,2);assert.equal(scene.elements.length,1);assert.equal(scene.selected,single[0]);assert.equal(scene.mode,'moment');assert.equal(scene.assets,assetsBeforeScene+1);await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  // A composition containing only plain text does not require a keyframe selection.
  const textOnly=await fresh();for(const id of textOnly.filter(id=>id!==textOnly[4]))await remove(id);assert.deepEqual(await layers(),[textOnly[4]]);assert.equal(await page.$eval('[data-motion-key-panel]',n=>n.hidden),true);await page.click('[data-motion-insert-group]');const textGroup=await page.evaluate(()=>{const gs=sec().elements.filter(e=>e.nwMotionInstance),g=gs[gs.length-1];return {gid:g.id,members:sec().elements.filter(e=>e.parent===g.id),selected:selection[0],mode:NAGWEB_STORY_EDITOR.canvasMode(),assets:project.assets.images.length};});assert.equal(textGroup.members.length,1);assert.equal(textGroup.members[0].type,'heading');assert.equal(textGroup.selected,textOnly[4]);assert.equal(textGroup.mode,'base');assert.equal(textGroup.assets,saved.assets);await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),textGroup.gid);await frame();await page.click('[data-motion-library-tab="elements"]');await choose(textOnly[4]);assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await page.click('[data-motion-close]');await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  console.log('Quitar elementos Motion Lab: borrador/lienzo/lista sincronizados, recursos usados, guardar altas y bajas en misma instancia, externos y supervivientes intactos, cancelar, historial, exportación, una lámina y solo texto OK');
 }finally{
  await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#remove-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
